export async function* pagedReportRows(filter: ReportFilter) {
  let after = 0;
  for (;;) {
    const rows = await db.query(buildSql(filter, { afterId: after, limit: 1000 }));
    if (rows.length === 0) return;
    yield rows;
    after = rows[rows.length - 1].id;
  }
}

