green.sketch:
export function csvStream(filter: ReportFilter): Readable {
  return Readable.from((async function* () {
    yield formatRow(COLUMNS) + '\n';
    for await (const page of pagedReportRows(filter)) for (const row of page) yield formatRow(COLUMNS.map(c => row[c])) + '\n';
  })());
}

